-- ============================================================
-- Add products from the Sep 2026 supplier price list
-- Prices are LIST prices (no discounts here: discounts are set from the admin
-- panel via supplier_discounts / promotional_discounts, per category + brand).
--
-- Safety:
--   * every product is inserted with published = false -> nothing is visible to
--     visitors until reviewed and published from the admin dashboard
--   * no supplier / importer name is stored anywhere
--   * guarded: aborts if any of the new brands already exist (prevents double run)
--   * nothing existing is updated or deleted
-- ============================================================

begin;

do $$
begin
  if exists (select 1 from public.products where brand in
      ('Huawei','Lesso','MUST','Phylion','NPP','Luminous','Himel','KEWO','SunX Power','HIS','KUKA Cable')) then
    raise exception 'Sep 2026 price-list products appear to be already imported - aborting';
  end if;
end $$;

-- New categories: hidden until the matching front-end code is deployed.
on conflict (category_key) do nothing;

-- Solar panels - Longi (price on request: unpublished, no price)

-- On-grid inverters - Huawei (three-phase)

-- EV chargers (new category: ev_chargers)

-- Batteries - MUST lithium

-- Batteries - Phylion lithium

-- Batteries - NPP gel

-- Batteries - Luminous tubular

-- Off-grid inverters - MUST

-- Hybrid inverters - MUST

-- Pump inverters - Himel (900VDC)

-- Reactors - KEWO (new category: reactors)

-- DC protections - SunX Power / Kayal / Suntree (category: accessories)

-- DC cables - HIS / KUKA Cable (price per meter)

-- Charge controllers - SunX Power (new category: charge_controllers)

commit;
